window.ScripturaLexicons.BDAG_PART_0247 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-01\" data-source=\"BDAG\" data-search=\"νόσος, ου, ἡ substantivo feminino doença física; enfermidade moral BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νόσος, ου, ἡ</td><td>substantivo feminino</td><td>doença física; enfermidade moral</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-02\" data-source=\"BDAG\" data-search=\"νοσσιά, ᾶς, ἡ substantivo feminino ninho; ninhada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νοσσιά, ᾶς, ἡ</td><td>substantivo feminino</td><td>ninho; ninhada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-03\" data-source=\"BDAG\" data-search=\"νοσσίον, ου, τό substantivo neutro filhote de ave BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νοσσίον, ου, τό</td><td>substantivo neutro</td><td>filhote de ave</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-04\" data-source=\"BDAG\" data-search=\"νοσσός, οῦ, ὁ substantivo masculino filhote de ave; pombinho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νοσσός, οῦ, ὁ</td><td>substantivo masculino</td><td>filhote de ave; pombinho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-05\" data-source=\"BDAG\" data-search=\"νοσφίζω verbo médio reter para si; reservar indevidamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νοσφίζω</td><td>verbo médio</td><td>reter para si; reservar indevidamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-06\" data-source=\"BDAG\" data-search=\"νότος, ου, ὁ substantivo masculino vento sul; sul BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νότος, ου, ὁ</td><td>substantivo masculino</td><td>vento sul; sul</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-07\" data-source=\"BDAG\" data-search=\"νουθεσία, ας, ἡ substantivo feminino admoestação; instrução; repreensão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νουθεσία, ας, ἡ</td><td>substantivo feminino</td><td>admoestação; instrução; repreensão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-08\" data-source=\"BDAG\" data-search=\"νουθετέω verbo advertir; admoestar; instruir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νουθετέω</td><td>verbo</td><td>advertir; admoestar; instruir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-09\" data-source=\"BDAG\" data-search=\"νουθέτημα, ατος, τό substantivo neutro admoestação; disciplina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νουθέτημα, ατος, τό</td><td>substantivo neutro</td><td>admoestação; disciplina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-10\" data-source=\"BDAG\" data-search=\"νουθέτησις, εως, ἡ substantivo feminino admoestação; advertência; censura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νουθέτησις, εως, ἡ</td><td>substantivo feminino</td><td>admoestação; advertência; censura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-11\" data-source=\"BDAG\" data-search=\"νουμηνία remissão; variante de leitura ver νεομηνία BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νουμηνία</td><td>remissão; variante de leitura</td><td>ver νεομηνία</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-12\" data-source=\"BDAG\" data-search=\"νουνεχῶς advérbio com sabedoria; sensatamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νουνεχῶς</td><td>advérbio</td><td>com sabedoria; sensatamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-13\" data-source=\"BDAG\" data-search=\"νοῦς, νοός, νοί̈, νοῦν, ὁ substantivo masculino intelecto; entendimento; disposição mental; opinião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νοῦς, νοός, νοί̈, νοῦν, ὁ</td><td>substantivo masculino</td><td>intelecto; entendimento; disposição mental; opinião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-14\" data-source=\"BDAG\" data-search=\"Νύμφα, ας, ἡ nome próprio feminino Ninfa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νύμφα, ας, ἡ</td><td>nome próprio feminino</td><td>Ninfa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-15\" data-source=\"BDAG\" data-search=\"Νυμφᾶς, ᾶ, ὀ nome próprio masculino Ninfas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νυμφᾶς, ᾶ, ὀ</td><td>nome próprio masculino</td><td>Ninfas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-16\" data-source=\"BDAG\" data-search=\"νύμφη, ης, ἡ substantivo feminino noiva; nora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νύμφη, ης, ἡ</td><td>substantivo feminino</td><td>noiva; nora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-17\" data-source=\"BDAG\" data-search=\"νυμφικός, ή, όν adjetivo nupcial; próprio dos noivos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νυμφικός, ή, όν</td><td>adjetivo</td><td>nupcial; próprio dos noivos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-18\" data-source=\"BDAG\" data-search=\"νυμφίος, ου, ὁ substantivo masculino noivo; esposo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νυμφίος, ου, ὁ</td><td>substantivo masculino</td><td>noivo; esposo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-19\" data-source=\"BDAG\" data-search=\"νυμφών, ῶνος, ὁ substantivo masculino salão de bodas; câmara nupcial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νυμφών, ῶνος, ὁ</td><td>substantivo masculino</td><td>salão de bodas; câmara nupcial</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0247-20\" data-source=\"BDAG\" data-search=\"νῦν advérbio temporal agora; no presente; nas circunstâncias atuais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νῦν</td><td>advérbio temporal</td><td>agora; no presente; nas circunstâncias atuais</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0247-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόσος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νόσος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (Hom. e posteriores).</p><p class=\"entry-text\">① Mal físico, doença, enfermidade (frequentemente considerada depreciativa do ponto de vista social nas sociedades mediterrâneas), literalmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:12</a>; <span class=\"greek\">πεσούσης</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">ν</span>., quando (Artemila) … adoeceu AcPl Ha 4, 15 (cf. ApcMos 5 <span class=\"greek\">περιπεσὼν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ν</span>.). Com <span class=\"greek\">μαλακία</span>: <span class=\"greek\">θεραπεύειν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ν</span>., curar toda enfermidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:23</a>; 9:35; 10:1 (cf. Jos., Bell. 5, 383 <span class=\"greek\">πάσῃ</span> <span class=\"greek\">ν</span>.). <span class=\"greek\">νόσους</span> <span class=\"greek\">θεραπεύειν</span>, curar doenças <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:1</a> (Just., A I, 48, 1 <span class=\"greek\">πάσας</span> <span class=\"greek\">ν</span>.). Com <span class=\"greek\">βάσανοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>. <span class=\"greek\">ἐθεράπευσεν</span> <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">κακῶς</span> <span class=\"greek\">ἔχοντας</span> <span class=\"greek\">ποικίλαις</span> <span class=\"greek\">ν</span>., curou muitos que estavam enfermos de diversas doenças <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:34</a> (Tat. 20, 2 <span class=\"greek\">ποικίλαι</span> <span class=\"greek\">ν</span>.). <span class=\"greek\">ἀσθενοῦντες</span> <span class=\"greek\">νόσοις</span> <span class=\"greek\">ποικίλαις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:40</a>. <span class=\"greek\">ἐθεράπευσεν</span> <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">νόσων</span>, curou muitas pessoas de suas doenças 7:21. Passivo <span class=\"greek\">ἰαθῆναι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ν</span>. 6:18. Em linguagem figurada: <span class=\"greek\">βαστάζειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τινός</span>, levar as enfermidades de alguém (segundo Is 53:4, onde, contudo, a LXX não emprega <span class=\"greek\">νόσος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:17</a>; IPol 1:3.</p><p class=\"entry-text\">② Enfermidade moral, doença, extensão figurada de 1: vício (Bias em Diog. L. 1, 86 <span class=\"greek\">νόσος</span> <span class=\"greek\">ψυχῆς</span> acerca de defeito de caráter; Just., D. 30, 1 <span class=\"greek\">τὸν</span> <span class=\"greek\">λαὸν</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">νόσῳ</span> <span class=\"greek\">ψυχικῇ</span> <span class=\"greek\">ὑπάρχοντα</span>; Herm. Wr. 12, 3 <span class=\"greek\">ἀθεότης</span>; frequentemente em Philo): <span class=\"greek\">ὁ</span> <span class=\"greek\">μοιχὸς</span> … <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰδίᾳ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱκανὸν</span> <span class=\"greek\">ποιεῖ</span>, o adúltero satisfaz a própria inclinação doentia Hs 6, 5, 5.—MGrmek, Diseases in the Ancient Greek World, tradução de M e LMueller, ’89 [original francês ’83].—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσσιά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νοσσιά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">νόσσος</span>; forma do grego helenístico em lugar de <span class=\"greek\">νεοσσιά</span>, ver B-D-F §31, 3; Mlt-H. 92; Thackeray p. 98; Lob. acerca de Phryn. p. 207).</p><p class=\"entry-text\">① Ninho (neste sentido Hdt., Aristoph. e outros; LXX): <span class=\"greek\">νοσσιᾶς</span> <span class=\"greek\">ἀφῃρημένοι</span>, depois de terem seu ninho roubado 11:3.</p><p class=\"entry-text\">② Ninhada (Lycurgus, o orador [IV b.c.] 132; Dt 32:11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:34</a>; GJs 3:1 v.l.—DELG s.v. <span class=\"greek\">νεοσσός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσσίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νοσσίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">νοσσός</span>; forma do grego helenístico em lugar de <span class=\"greek\">νεοσσίον</span>; cf. <span class=\"greek\">νοσσιά</span>), filhote de ave <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a> (a palavra, na forma <span class=\"greek\">νεοττίον</span>, em Aristoph. e outros; como <span class=\"greek\">νοσσίον</span> também em Ps 83:4).—B. 175. DELG s.v. <span class=\"greek\">νεοσσός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσσός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νοσσός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (forma do grego helenístico por hiférese de <span class=\"greek\">νεοσσός</span> [cf. <span class=\"greek\">νοσσιά</span> e Jos., C. Ap. 2, 213 <span class=\"greek\">νεοττός</span>], como variante de leitura em Lk), filhote de ave (como <span class=\"greek\">νεοσσός</span> em Hom. e outros) 11:3 (cf. Is 16:2). <span class=\"greek\">δύο</span> <span class=\"greek\">νοσσοὺς</span> <span class=\"greek\">περιστερῶν</span>, dois pombinhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:24</a> (Lev 12:8; 14:22.—Soranus p. 72, 15 <span class=\"greek\">νεοσσοὺς</span> <span class=\"greek\">περιστερῶν</span>.—<span class=\"greek\">νοσσοί</span> acerca de filhotes de pombos: Sb 7814, 15 [256 a.d.]).—DELG s.v. <span class=\"greek\">νεοσσός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσφίζω</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νοσφίζω</span> (<span class=\"greek\">νόσφι</span>, «à parte»; Hom. e outros), em nossa literatura somente no médio; 1º aoristo <span class=\"greek\">ἐνοσφισάμην</span>, separar para si, reter, quanto à participação numa espécie de apropriação de parte de um montante (X., Cyr. 4, 2, 42: Ciro exorta à moderação na apropriação de tesouros; Polyb. 10, 16, 6: soldados romanos resistem à tentação de tomar para si espólios sem distribuição equitativa; Plut., Lucull. 517 [37, 2], Aristid. 320 [4, 3]; Jos., Ant. 4, 274; SIG 993, 21; PRyl 116, 10; 2 Macc 4:32): <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, parte de alguma coisa (PSI 442, 4 [III b.c.]; Josh 7:1.—<span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> Athen. 6, 23a; Philo, Mos. 1, 253): <span class=\"greek\">ἐνοσφίσατο</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τιμῆς</span>, (Ananias) reteve parte do produto da venda (não se trata de caso de desfalque) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:2</a>f (cf. Josh 7:1, 19–26. Diod S 5, 34, 3: proprietários de lotes que retêm [<span class=\"greek\">νοσφίζεσθαι</span>] parte de suas colheitas, declaradas propriedade comum [<span class=\"greek\">κοινοποιεῖσθαι</span>], ficam sujeitos à pena de morte entre os váceos, uma tribo céltica). <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ὅλως</span> <span class=\"greek\">ν</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐπιθυμίαν</span> <span class=\"greek\">πονηράν</span>, não reter nem reservar absolutamente nada para satisfazer o próprio desejo vil Hs 9, 25, 2. Sem complemento (inscrições [I a.d.]: <span class=\"greek\">ΕΛΛΗΝΙΚΑ</span> 1, 1928, p. 18 linha 13; PPetr III, 56 [b], 10; 12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:10</a>.—DELG s.v. <span class=\"greek\">νόσφι</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νότος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νότος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>.</p><p class=\"entry-text\">① Vento que sopra da direção meridional, vento sul, vento sudoeste (Hom. e outros; LXX; Philo, Mos. 1, 120.—Appian, Bell. Civ. 5, 98 §410, sem dúvida é vento sudoeste): <span class=\"greek\">ὑποπνεύσαντος</span> <span class=\"greek\">νότου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:13</a> (ver <span class=\"greek\">ὑποπνέω</span>). <span class=\"greek\">ἐπιγενομένου</span> <span class=\"greek\">νότου</span>, quando surgiu o vento sudoeste 28:13. Traz calor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:55</a> (cf. Jos., Bell. 7, 318 <span class=\"greek\">νότος</span> <span class=\"greek\">πνεύσας</span>).</p><p class=\"entry-text\">② Direção à direita de quem olha para o leste, sul.</p><p class=\"entry-text\">ⓐ Da direção em geral (Soph.; Hdt. 6, 139 e outros; SIG 691, 18; POxy 255, 7; PTebt 342, 8; LXX; En 26:2; TestSol 7:6; TestJud 4:1; GrBar 11:8; ViIs, ViEzk, ViHab, ViJer e outros 7 [p. 70, 7 Sch.]; Jos., Bell. 5, 145, Ant. 8, 319): <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">βορρᾶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>., do norte e do sul (ver <span class=\"greek\">βορρᾶς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:29</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">νότου</span>, ao sul (<span class=\"greek\">ἀπό</span> 2a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:13</a>.</p><p class=\"entry-text\">ⓑ De uma região ou país meridional (Ps 125:4 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νότῳ</span>; ApcMos 15): <span class=\"greek\">βασίλισσα</span> <span class=\"greek\">νότου</span>, a rainha do sul (Sabá; TestSol 19:3 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:31</a>.—B. 873. DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουθεσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νουθεσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">νουθετέω</span>; Aristoph., Ran. 1009; Diod S 15, 7, 1; BGU 613, 21; PAmh 84, 21; Wsd 16:6; TestReub 3:8; Philo, Mos. 1, 119 e outros; Jos., Ant. 3, 311; Just., A I, 67, 4; Did.; Lob. acerca de Phryn. 512), conselho para evitar ou abandonar conduta imprópria, admoestação, instrução. Em geral, com <span class=\"greek\">παιδεία</span> (como em Philo, Deus Imm. 54; cf. De Mut. 135) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:4</a> <span class=\"greek\">νουθ</span>. <span class=\"greek\">κυρίου</span> (= instrução cristã).—Acerca de acontecimentos históricos usados como exemplo ou advertência para desencorajar conduta imprópria: <span class=\"greek\">γράφειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τινός</span>, escrever como advertência para alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:11</a> (<span class=\"greek\">πρὸς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τινός</span> como em Philo, De Praem. 133).—De repreensão discreta a respeito da repetição de conduta imprópria, admoestação, censura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:10</a>.—Ao lado de <span class=\"greek\">πίστις</span>, <span class=\"greek\">ὑπομονή</span>, <span class=\"greek\">μακροθυμία</span> IEph 3:1.—DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουθετέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νουθετέω</span>, futuro <span class=\"greek\">νουθετήσω</span>; 1º aoristo <span class=\"greek\">ἐνουθέτησα</span>. Passivo: particípio aoristo <span class=\"greek\">νουθετηθέντες</span> Wsd 12:26; perfeito, 2ª pessoa do singular <span class=\"greek\">νενουθέτησαι</span> Job 38:18 (ver verbete precedente; autores trágicos e outros; PGrenf II 93, 3; LXX; pseudoepígrafos; Philo; Jos., Ant. 4, 260; 20, 162; Did.), aconselhar a evitar ou abandonar conduta imprópria, admoestar, advertir, instruir, com acusativo de pessoa (Dio Chrys. 56 [73], 10; Sb 6263, 26) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:14</a> (Wsd 11:10 <span class=\"greek\">τούτους</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">νουθετῶν</span>; PsSol 13:9; Jos., Bell. 1, 481, Ant. 3, 311); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:28</a>; 3:16 (nas duas últimas passagens, com <span class=\"greek\">διδάσκειν</span>, como em Pla., Leg. 8, 84b; Philo, Decal.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:11</a> v.l.; 1 Cl 7:1; 2 Cl 19:2. <span class=\"greek\">ἀλλήλους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:14</a>; 2 Cl 17:2. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀτάκτους</span>, advertir os ociosos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:14</a> («punir», como em Plut., Sertor. 578 [19, 11] <span class=\"greek\">πληγαῖς</span> <span class=\"greek\">ν</span>., provavelmente é um sentido forte demais). <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> Hv 1, 3, 1; também <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> 1, 3, 2. <span class=\"greek\">τὰς</span> <span class=\"greek\">χήρας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀρφανούς</span> 2, 4, 3. <span class=\"greek\">ἁμαρτάνοντας</span> m 8:10. Passivo <span class=\"greek\">νουθετεῖσθαι</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> (Philo, Deus Imm. 134; Jos., Ant. 20, 162a) 2 Cl 17:3; Hv 3, 5, 4.—DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουθέτημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νουθέτημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">νοῦς</span>, <span class=\"greek\">τίθημι</span>; Aeschyl. e outros; também Herodas 7, 11), admoestação, disciplina 1 Cl 56:6 (Job 5:17).—DELG s.v. <span class=\"greek\">νόος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουθέτησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νουθέτησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">νοῦς</span>, <span class=\"greek\">τίθημι</span>; desde Eupolis Com. [Vb.c.] 66; Pla.; Diod S 1, 70, 8; 1, 77, 7; 3, 33, 5; Iambl., Vi. Pyth. 33, 231; Jdth 8:27; Pr 2:2), admoestação, advertência, repreensão: <span class=\"greek\">ἡ</span> <span class=\"greek\">ν</span>., <span class=\"greek\">ἣν</span> <span class=\"greek\">ποιούμεθα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀλλήλους</span>, a repreensão que dirigimos uns aos outros 1 Cl 56:2.—DELG s.v. <span class=\"greek\">νόος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουμηνία</h1><div class=\"entry-meta\"><span>remissão; variante de leitura</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νουμηνία</span>, leitura adotada por Tdf. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:16</a>; ver <span class=\"greek\">νεομηνία</span>.—DELG s.v. 2 <span class=\"greek\">μήν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουνεχῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νουνεχῶς</span> (Aristot. 1436b, 33 <span class=\"greek\">νουνεχῶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δικαίως</span>; Polyb. 1, 83, 3; 2, 13, 1; 5, 88, 2; SibOr 1, 7; TestJob 36:6), advérbio de <span class=\"greek\">νουνεχής</span> (Just.), sabiamente, sensatamente: <span class=\"greek\">ἀποκρίνεσθαι</span>, responder <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:34</a>.—DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοῦς, νοός, νοί̈, νοῦν, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νοῦς</span>, <span class=\"greek\">νοός</span>, <span class=\"greek\">νοί</span>̈, <span class=\"greek\">νοῦν</span>, <span class=\"greek\">ὁ</span> (contraído de <span class=\"greek\">νόος</span>.—Hom. e outros; papiros, LXX, TestSol, Test12Patr; SibOr 3, 574; EpArist 276; Philo [frequentemente]; Jos., Ant. 3, 65, Vi. 122 e outros; apologistas, exceto Mel.—Sobre a declinação, ver B-D-F §52; W-S. §8, 11; Mlt-H. 127; 142), no NT somente na literatura paulina, exceto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:18</a>; 17:9.</p><p class=\"entry-text\">① Faculdade de percepção intelectual.</p><p class=\"entry-text\">ⓐ Mente, intelecto, como aspecto da vida contrastado com a existência física, a parte superior, mental, do ser humano que inicia pensamentos e planos (Apollonius de Tyana [I a.d.] em Eus., PE 4, 13; Orig., C. Cels. 8, 38, 21; 52, 24; Did., Gen. 57, 26): <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοός</span> (<span class=\"greek\">μου</span>), a lei do (meu) intelecto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:22</a> v.l., 23. (Em oposição a <span class=\"greek\">σάρξ</span>) <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">δουλεύειν</span> <span class=\"greek\">νόμῳ</span> <span class=\"greek\">θεοῦ</span>, servir à lei de Deus com o próprio intelecto, versículo 25.</p><p class=\"entry-text\">ⓑ Entendimento, mente, como faculdade de pensar (Hippol., Ref. 4, 43, 2; Did., Gen. 44, 11 [com <span class=\"greek\">λογισμός</span>]): <span class=\"greek\">διανοίγειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τινος</span>, abrir a mente de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:45</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">νοῦν</span>, quem tem entendimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:18</a> (<span class=\"greek\">ν</span>. <span class=\"greek\">ἔχειν</span> como em Aristoph., Equ. 482; Hyperid. 3, 23; Dio Chrys. 17 [34], 39; 23 [40], 26; Ael. Aristid. 23, 12 K.=42 p. 771 D.; EpArist 276; Philo, Mos. 1, 141; TestReub 3:8; Ar. 9, 5; Just., D. 30, 1; 60, 2; Tat. 1, 2). <span class=\"greek\">ὧδε</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">σοφίαν</span>, aqui está (isto é, isto exige) uma mente dotada de sabedoria 17:9. <span class=\"greek\">νοῦν</span> <span class=\"greek\">διδόναι</span>, conceder entendimento Dg 10:2. Também <span class=\"greek\">παρέχειν</span> <span class=\"greek\">νοῦν</span> 11:5. <span class=\"greek\">ὁ</span> <span class=\"greek\">σοφίαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νοῦν</span> <span class=\"greek\">θέμενος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κρυφίων</span> <span class=\"greek\">αὐτοῦ</span>, aquele que colocou em nós sabedoria e entendimento dos seus mistérios 6:10. <span class=\"greek\">ποικίλος</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φρονήσει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>., diverso em pensamento e entendimento Hs 9, 17, 2a; cf. versículo 2b. Acerca da paz de Deus: <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπερέχουσα</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ν</span>., que ultrapassa toda capacidade de pensar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:7</a>. Em contraste com o Pneuma divino que inspira o «que fala em línguas»: <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">μου</span> <span class=\"greek\">ἄκαρπός</span> <span class=\"greek\">ἐστιν</span>, minha mente fica infrutífera, porque permanece inativa durante a glossolalia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:14</a>. <span class=\"greek\">προσεύχεσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>. (em oposição a <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span>.—<span class=\"greek\">νόῳ</span> como dativo instrumental, como Pind., P. 1, 40), orar com o entendimento, versículo 15a; <span class=\"greek\">ψάλλειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>., cantar com o entendimento, versículo 15b. <span class=\"greek\">θέλω</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">μου</span> <span class=\"greek\">λαλῆσαι</span>, prefiro falar cinco palavras com meu entendimento, versículo 19 (cf. 1QS 10:9).—Como designação de Cristo (cf. SibOr 8, 284), numa longa série de expressões (com <span class=\"greek\">φῶς</span>) Dg 9:6 (cf. Epict. 2, 8, 2 <span class=\"greek\">τίς</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">οὐσία</span> <span class=\"greek\">θεοῦ</span>; <span class=\"greek\">νοῦς</span>, <span class=\"greek\">ἐπιστήμη</span>, <span class=\"greek\">λόγος</span> <span class=\"greek\">ὀρθός</span>. Theoph. Ant. 1, 3 [p. 62, 14] <span class=\"greek\">νοῦν</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">εἴπω</span>, <span class=\"greek\">φρόνησιν</span> <span class=\"greek\">αὐτοῦ</span> [sc. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>] <span class=\"greek\">λέγω</span>; Ath. 10, 2 <span class=\"greek\">νοῦς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>. O deus <span class=\"greek\">Νοῦς</span> nos Herm. Wr.: Rtzst., Mysterienrel3 47 e outros; JKroll, D. Lehren des Hermes Trismegistos 1914, 10ff; 60ff e outros; PGM 5, 465 <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">Νοῦς</span>; Iren. 1, 1, 1 [Harv. I 9, 7], 1, 2, 1 [Harv. I 13, 7]: nomes de éons na especulação gnóstica).—Também o estado de sensatez e serenidade, em contraste com as perturbações da alma causadas pela expectativa da Parusia: <span class=\"greek\">σαλευθῆναι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοός</span>, ser abalado e, com isso, perder a tranquilidade mental <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a>.</p><p class=\"entry-text\">② Modo de pensar, mente, atitude, como totalidade da condição mental e moral de uma pessoa (Just., A I, 15, 16).</p><p class=\"entry-text\">ⓐ Como algo possuído por cada pessoa: <span class=\"greek\">μεταμορφοῦσθαι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀνακαινώσει</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>., transformar-se pela renovação da mente, que ocorre quando os cristãos têm seu <span class=\"greek\">νοῦς</span> natural penetrado e transformado pelo Espírito que recebem no batismo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:2</a> (ver Ltzm., Hdb. ad loc.). No mesmo sentido, <span class=\"greek\">ἀνανεοῦσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ὑμῶν</span>, deveis adotar uma nova atitude mental <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:23</a> (o acúmulo de sinônimos é característica peculiar de Eph; ver MDibelius, Hdb. excursus sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:14</a>). Acerca dos politeístas: <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀδόκιμον</span> <span class=\"greek\">ν</span>., Deus os entregou a pensamentos depravados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:28</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">περιπατεῖ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ματαιότητι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">αὐτῶν</span>, as nações/os gentios vivem com a mente presa a coisas vãs <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:17</a>. Acerca de alguém que está em erro: <span class=\"greek\">εἰκῇ</span> <span class=\"greek\">φυσιούμενος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">αὐτοῦ</span>, envaidecido sem razão (literalmente «inchado») pela própria mente, fixada em coisas puramente físicas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:18</a>. <span class=\"greek\">κατεφθαρμένος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>., com mente depravada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:8</a>; também <span class=\"greek\">διεφθαρμένος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:5</a> (B-D-F §159, 3; Rob. 486). <span class=\"greek\">μεμίανται</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">συνείδησις</span>, suas mentes e consciências estão impuras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:15</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρᾶξιν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">καταγίνεται</span>, sua mente está voltada aos próprios negócios Hm 10, 1, 5.</p><p class=\"entry-text\">ⓑ Especificamente sobre a atitude ou maneira de pensar cristã: <span class=\"greek\">κατηρτισμένοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">νοί</span>̈ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:10</a>. Pelo batismo os crentes recebem <span class=\"greek\">μίαν</span> <span class=\"greek\">φρόνησιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">νοῦν</span> Hs 9, 17, 4; cf. 9, 18, 4. <span class=\"greek\">εἷς</span> <span class=\"greek\">νοῦς</span>, <span class=\"greek\">μία</span> <span class=\"greek\">ἐλπίς</span> deve prevalecer na igreja IMg 7:1.</p><p class=\"entry-text\">③ Resultado do pensamento, mente, pensamento, opinião, decisão (Hom. e outros, acerca de deuses e seres humanos; cf. Hippol., Ref. 9, 10, 8): <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἰδίῳ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">πληροφορείσθω</span>, cada pessoa deve estar plenamente convencida na própria mente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:5</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἔγνω</span> <span class=\"greek\">νοῦν</span> <span class=\"greek\">κυρίου</span>;, pois quem conheceu os pensamentos do Senhor? (Is 40:13) 11:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:16</a>a. Quando Paulo continua na última passagem, versículo 16b, com <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">νοῦν</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">ἔχομεν</span>, ele emprega a palavra escriturística <span class=\"greek\">νοῦς</span> para designar o que usualmente chama <span class=\"greek\">πνεῦμα</span> (versículos 14f). Pode fazê-lo porque o seu <span class=\"greek\">νοῦς</span> (pois é pessoa «pneumática») está cheio do Espírito (ver 2a acima), de modo que, no caso dele, os dois são intercambiáveis. Um <span class=\"greek\">νοῦς</span> dessa espécie é impossível para uma pessoa «psíquica».—OMoe, Vernunft u. Geist im NT: ZST 11, ’34, 351–91; RJewett, Paul’s Anthropological Terms, ’71, 358–90; TKrischer, Glotta 62, ’84, 141–49. Ver <span class=\"greek\">καρδία</span>, final; <span class=\"greek\">νοέω</span>, final.—B. 1198. DELG s.v. <span class=\"greek\">νόος</span>. Schmidt, Syn. III 621–55. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νύμφα, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νύμφα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ático <span class=\"greek\">Νύμφη</span>, <span class=\"greek\">ης</span>; assim PHib 94, 8 [III b.c.]; Stud-Pal 10, 1910, nº 113, 2 [II a.d.]), Ninfa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:15</a>. A forma <span class=\"greek\">Νυμφαν</span> dos manuscritos é seguramente acusativa, mas poderia derivar igualmente do masculino <span class=\"greek\">Νυμφᾶς</span> (cf. as variantes de leitura <span class=\"greek\">αὐτῶν</span> e <span class=\"greek\">αὐτοῦ</span> e ver o próximo verbete), a menos que, como em N., se prefira <span class=\"greek\">αὐτῆς</span> (Metzger 627) com a expressão <span class=\"greek\">τὴν</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">οἶκον</span> <span class=\"greek\">ἐκκλησίαν</span>. (Sobre o papel de mulheres como benfeitoras, ver, por exemplo, a inscrição em homenagem a Iounia Theodora: BCH 83, ’59, 496ff. [=Pleket nº 8].)—B-D-F §125, 1; Mlt. 48. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νυμφᾶς, ᾶ, ὀ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νυμφᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὀ</span> (CIG I, 269, 15; 1240, 18f; provavelmente forma abreviada de <span class=\"greek\">Νυμφόδωρος</span>; ver <span class=\"greek\">Νύμφα</span>), Ninfas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:15</a> v.l. (como acusativo <span class=\"greek\">Νυμφᾶν</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύμφη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νύμφη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom. e posteriores; inscrições, papiros, LXX, Philo, Joseph.; TestJud 13:3; JosAs, Philo, Joseph., Mel.; PBodm XII <span class=\"greek\">νύμφαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νυμφίοι</span>; empréstimo no rabínico; a igreja como noiva de Cristo Did., Gen. 69, 14).</p><p class=\"entry-text\">① Noiva (Diod S 5, 2, 3; Iren. 5, 9, 4 [Harv. II 344, 11]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:2</a>. Com <span class=\"greek\">νυμφίος</span> (q.v.; Did., Gen. 63, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:1</a> v.l. (ver FBurkitt, JTS 30, 1929, 267–70); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:23</a> (Jer 7:34; 16:9 e outros). Da noiva do Cordeiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:9</a>; cf. 22:17 (CChavasse, The Bride of Christ ’40).—Pode designar também a mulher recém-casada (Istros [III b.c.]: 334 Fgm. 55 Jac.; Iren. 4, 20, 12 [Harv. II 224, 2]).</p><p class=\"entry-text\">② Nora (Gen 11:31; 38:11; Ruth 1:6, 22 e outros; Philo, Leg. All. 3, 74; Jos., Ant. 5, 321; SibOr 1, 206; 3, 827.—=«filha» em inscrições da Ásia Menor: ENachmanson, Eranos 9, 1909, 78) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:53</a> (para ambos, cf. Mi 7:6).—RBatey, NT Nuptial Imagery ’71.—B. 125. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νυμφικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">νύμφη</span>; Aeschy., Pl. e outros; TestJud 12:1; papiros), nupcial: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">νυμφικά</span>, as vestes nupciais GJs 2:4.—DELG s.v. <span class=\"greek\">νύμφη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφίος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νυμφίος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">νύμφη</span>; Hom. e outros; SIG 1024, 33f [c. 200 b.c.]; CPR I, 30, 37; Sb 10; LXX, JosAs, Mel., PBodmer XII.—Na especulação gnóstica: Iren. 1, 7, 1 [Harv. I 58, 9]; Hippol., Ref. 6, 34, 4), noivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:15</a>bc; 25:1, 5f, 10 (sobre a chegada do noivo, cuja aparência supera em esplendor todos os outros mortais, cf. Sappho 123 Diehl2, 5 [=Campbell 111]: «muito maior do que um homem grande»); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:19</a>f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:34</a>f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:9</a>; 3:29ac; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:23</a> (com <span class=\"greek\">νύμφη</span> [q.v. 1] como em Diod S 5, 18, 1; Philo, Spec. Leg. 1, 110; Jos., Bell. 6, 301). <span class=\"greek\">ὁ</span> <span class=\"greek\">φίλος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>. (1 Macc 9:39; cf. Jos., Ant. 13, 20), o amigo do noivo (<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">שׁוֹשְׁבִין</span>), atuava como intermediário na organização do casamento e depois ocupava posição de destaque nas festividades nupciais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:29</a>b. <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νυμφίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:15</a>a D certamente não é a leitura original (Jülicher, Gleichn. 180f).—DELG s.v. <span class=\"greek\">νύμφη</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφών, ῶνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νυμφών</span>, <span class=\"greek\">ῶνος</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">νύμφη</span>).</p><p class=\"entry-text\">① Salão de bodas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:10</a> v.l.</p><p class=\"entry-text\">② Câmara nupcial (Paus. 2, 11, 3; Heliod. 7, 8, 3; PLond III, 964, 19 p. 212 [II/III a.d.]; Tob 6:14, 17; JosAs 15:7 [ver Philonenko 89]; Clem. de Al., Exc. ex Theod. §64f) Hv 4, 2, 1. <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νυμφῶνος</span> (genitivo como em Ps 149:2; 1 Macc 4:2 <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἄκρας</span>), os acompanhantes do noivo, aquele grupo de convidados do casamento que ficava mais próximo do noivo e desempenhava papel essencial na cerimônia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:34</a> (ver FLewis, ET 24, 1913, 285).—Billerb. I 500–518. DELG s.v. <span class=\"greek\">νύμφη</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0247-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῦν</h1><div class=\"entry-meta\"><span>advérbio temporal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νῦν</span>, advérbio temporal (Hom. e posteriores), «agora».</p><p class=\"entry-text\">① Marcador temporal com enfoque no momento em si, agora.</p><p class=\"entry-text\">ⓐ Do tempo coincidente com o acontecimento narrado, agora, no momento presente, com enfoque no presente imediato, designando tanto um ponto temporal quanto sua duração.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Sem artigo definido. Os verbos com que é empregado encontram-se:</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">א</span> . No presente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:18</a>; 9:21; 16:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:2</a> e frequentemente.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ב</span> . No perfeito, quando possui sentido de presente: <span class=\"greek\">ἔρχεται</span> <span class=\"greek\">ὥρα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἐλήλυθεν</span>, agora chegou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:32</a> v.l.; <span class=\"greek\">ν</span>. <span class=\"greek\">ἐγνώκαμεν</span>, agora sabemos 8:52; cf. 17:7. <span class=\"greek\">ν</span>. <span class=\"greek\">οἶδα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:11</a>. <span class=\"greek\">ν</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span> <span class=\"greek\">μου</span> <span class=\"greek\">τετάρακται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:27</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:18</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ג</span> . No aoristo, sobretudo em contraste com o passado, indicando que uma ação ou condição começa no presente: <span class=\"greek\">νῦν</span> <span class=\"greek\">ἐδοξάσθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span>, agora começou a glorificação do Filho do Homem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:31</a>. <span class=\"greek\">ν</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">καταλλαγὴν</span> <span class=\"greek\">ἐλάβομεν</span>, agora entramos na reconciliação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:11</a>. <span class=\"greek\">οὗτοι</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἠπείθησαν</span>, agora se tornaram desobedientes 11:31. <span class=\"greek\">ν</span>. <span class=\"greek\">ἀπεκαλύφθη</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἁγίοις</span> <span class=\"greek\">ἀποστόλοις</span>, agora foi revelado aos santos apóstolos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:5</a>; cf. versículo 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:10</a>. <span class=\"greek\">ἃ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἀνηγγέλη</span> <span class=\"greek\">ὑμῖν</span>, aquilo que agora vos é anunciado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:12</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:9</a>; 16:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:10</a>b, 25.—Mais raramente em contraste com o futuro: <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνασαί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἀκολουθῆσαι</span>, <span class=\"greek\">ἀκολουθήσεις</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὕστερον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:36</a> (<span class=\"greek\">νῦν</span> … <span class=\"greek\">ὕστερον</span> como em Jos., Ant. 4, 295). <span class=\"greek\">ἵνα</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἔλθῃ</span>· <span class=\"greek\">ἐλεύσεται</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:12</a>. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λάβῃ</span> … <span class=\"greek\">ν</span>., explicado por <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">καιρῷ</span> <span class=\"greek\">τούτῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:30</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ד</span> . No imperativo, para indicar que a ordem ou pedido deve ser cumprido imediatamente; <span class=\"greek\">ν</span>. vem depois do imperativo (B-D-F §474, 3; antes do imperativo: TestAbr A 6 p. 83, 24 [Stone p. 14] <span class=\"greek\">νῦν</span> <span class=\"greek\">θέασαι</span>): <span class=\"greek\">καταβάτω</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>, desça agora da cruz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:32</a>. <span class=\"greek\">ῥυσάσθω</span> <span class=\"greek\">ν</span>., que (Deus) o livre agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:43</a>. <span class=\"greek\">ἀντλήσατε</span> <span class=\"greek\">ν</span>., tirai agora um pouco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:8</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com artigo definido.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">א</span> . Como adjetivo: <span class=\"greek\">ὁ</span>, <span class=\"greek\">ἡ</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">νῦν</span>, o presente, atual (X., An. 6, 6, 13 <span class=\"greek\">ὁ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">χρόνος</span>; Dio Chrys. 19 [36], 55 <span class=\"greek\">ὁ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">κόσμος</span>; PAmh 68, 66 <span class=\"greek\">ὁ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">στρατηγός</span>; BGU 19, 5; GrBar 4:16 <span class=\"greek\">οἱ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἄνθρωποι</span>; Just., D. 68, 8 <span class=\"greek\">ἡ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ὁμιλία</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">αἰών</span>, a presente era <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:12</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">καιρός</span> (Ael. Aristid. 13 p. 239 D.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:26</a>; 8:18; 11:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:14</a>; 4:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">Ἰερουσαλήμ</span>, a Jerusalém atual <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:25</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">οὐρανοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:7</a>. <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ν</span>. (em oposição a <span class=\"greek\">ἡ</span> <span class=\"greek\">μέλλουσα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:8</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ב</span> . Como substantivo: <span class=\"greek\">τὸ</span> <span class=\"greek\">νῦν</span>, o tempo presente (Aristot.), com preposição (X. e outros; inscrições, papiros, LXX): <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>., de agora em diante, no futuro (SIG 982, 22; BGU 153, 14; 193 II, 11; POxy 479, 6; cf. IXanthos 86 D, linha 8; ver LRobert, Nouvelles Inscriptions di Sardes ’64, 28f [outros exemplos em Dssm., NB 81=BS 253]; Sir 11:23f; Tob 7:12; 1 Macc 10:41; 11:35; 15:8; ApcMos 28; Jos., Ant. 13, 50) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:48</a>; 5:10; 12:52; 22:69; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:16</a>a; <span class=\"greek\">ἄχρι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>., até agora (ver <span class=\"greek\">ἄχρι</span> 1a<span class=\"greek\">α</span>.—<span class=\"greek\">μέχρι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>.: Just., D. 78, 8; Diod S 1, 22, 2; SIG 742, 35; BGU 256, 9; 667, 8; 3 Macc 6:28; Jos., Ant. 3, 322) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:5</a>. <span class=\"greek\">ἕως</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>., até agora (SIG 705, 44f [112 b.c.]; PMich 173, 14 [III b.c.]; Gen 32:5; 46:34; 1 Macc 2:33) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:19</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ג</span> . Com outras partículas: <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">νῦν</span>, mas agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:16</a>b. <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>. (TestAbr A 16 p. 97, 5 [Stone p. 42]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:22</a>; <span class=\"greek\">ἄρα</span> <span class=\"greek\">ν</span>., portanto agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:1</a>. <span class=\"greek\">ν</span>. <span class=\"greek\">γάρ</span>, pois agora 13:11. <span class=\"greek\">ν</span>. <span class=\"greek\">δέ</span>, mas agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:25</a>; 19:42 (<span class=\"greek\">νῦν</span> <span class=\"greek\">δέ</span> também no tema da inversão de condição em Il. 19, 287–90; 22, 477–514 e outros); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:5</a>; 17:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:8</a>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ν</span>., nem mesmo agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:2</a> (<span class=\"greek\">ἔτι</span> <span class=\"greek\">ν</span>. = mesmo agora: Plut., Mor. 162e; Ael. Aristid. 13 p. 302 D.; Jos., Ant. 1, 92; 2, 313). <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>., mesmo agora (cf. Just., A I, 26, 4; 63, 1, D. 7, 2; Dio Chrys. 13 [7], 121) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:22</a> v.l. (talvez «certamente», mas ver HRiesenfeld, Nuntius 6, ’52, 41–44); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a>; <span class=\"greek\">ἔτι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>., e mesmo agora Dg 2:3 (Ath. 17, 2; cf. Just., A I, 26, 5 <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἔτι</span>, A II, 6, 6 <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">νῦν</span>); e agora (TestLevi 19:1; JosAs 28:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:37</a>; 23:21; 26:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:30</a>; AcPl Ha 8, 21. <span class=\"greek\">ν</span>. <span class=\"greek\">οὖν</span>, portanto agora (Gen 27:8; 1 Macc 10:71) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:36</a>; 23:15. <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>. … <span class=\"greek\">ἤδη</span>, e agora … já <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:3</a>. <span class=\"greek\">ν</span>. <span class=\"greek\">μέν</span>, agora, é verdade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:22</a>. <span class=\"greek\">ποτὲ</span> … <span class=\"greek\">ν</span>. <span class=\"greek\">δέ</span>, outrora … mas agora (Mel., P. 43, 306) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:10</a>. <span class=\"greek\">πολλάκις</span> … <span class=\"greek\">ν</span>. <span class=\"greek\">δέ</span>, frequentemente … mas agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:18</a>. <span class=\"greek\">τότε</span> (<span class=\"greek\">μὲν</span>) … <span class=\"greek\">ν</span>. <span class=\"greek\">δέ</span>, então … mas agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:26</a>. <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">τότε</span> … <span class=\"greek\">οὕτως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>., assim como então … assim também agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:29</a>.—ALaurentin, <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">וְעַתָּה</span>—<span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span>. Formule, etc. (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:5</a>): Biblica 45, ’64, 168–95; 413–32; HBronyers, … adverbiales <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">וְעַתָּה</span> im AT: VetusT 15, ’65, 289–99.</p><p class=\"entry-text\">ⓑ Do tempo pouco antes ou pouco depois do presente imediato: <span class=\"greek\">ν</span>. <span class=\"greek\">ἠκούσατε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:65</a>. <span class=\"greek\">ν</span>. <span class=\"greek\">ἐζήτουν</span> <span class=\"greek\">σε</span> <span class=\"greek\">λιθάσαι</span>, acabavam de procurar apedrejar-te <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:8</a>. Cf. 21:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.52\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:52</a>.—(Em breve) agora (Epict. 3, 24, 94): <span class=\"greek\">ν</span>. <span class=\"greek\">ἀπολύεις</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δοῦλόν</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:29</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:31</a>ab; 16:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a>.</p><p class=\"entry-text\">② Marcador temporal que focaliza não tanto o tempo presente quanto a situação existente em dado momento, agora, tal como as coisas estão.</p><p class=\"entry-text\">ⓐ Sem artigo: como as coisas agora se apresentam (Gen 29:32; Ps.-Clem., Hom. 10, 22): <span class=\"greek\">νῦν</span> <span class=\"greek\">ζῶμεν</span> <span class=\"greek\">ἐάν</span>, na situação atual, vivemos se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:8</a>. Assim também <span class=\"greek\">νῦν</span> <span class=\"greek\">δέ</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span>, <span class=\"greek\">νῦν</span> <span class=\"greek\">οὖν</span>: <span class=\"greek\">νῦν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">τί</span> <span class=\"greek\">πειράζετε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>;, sendo assim, por que tentais a Deus? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:10</a>; cf. 10:33 (<span class=\"greek\">νῦν</span> <span class=\"greek\">οὖν</span>: TestAbr B 7 p. 112, 3 [Stone p. 72]; TestJob 23:7; ApcMos 11:30; Lucian, Dial. Deor. 25, 3; Babrius 6, 9). <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τί</span> <span class=\"greek\">μέλλεις</span>;, e agora, que esperas? 22:16 (cf. TestAbr A 4 p. 81, 18 [Stone p. 10] <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>., <span class=\"greek\">κύριε</span> <span class=\"greek\">τὶ</span> <span class=\"greek\">ποιήσω</span>;). Cf. 2J 5.—Às vezes em enunciados imperativos (frequentemente na LXX; cf. JJeremias, ZNW 38, ’39, 119f; PsSol 2:32; TestAbr A 4 p. 81, 5 [Stone p. 10]; TestSim 7:1; JosAs 6:8; GrBar 4:1; Tat. 21, 2 <span class=\"greek\">πείσθητέ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">νῦν</span>): <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">πέμψον</span>, envia agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:5</a>. Cf. 16:36; 23:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:28</a>; GJs 9:2.—Sobre <span class=\"greek\">ἄγε</span> <span class=\"greek\">νῦν</span>, ver <span class=\"greek\">ἄγε</span>.—Não raramente <span class=\"greek\">νῦν</span> <span class=\"greek\">δέ</span> serve para contrastar a situação real com o enunciado de oração condicional irreal: <span class=\"greek\">εἰ</span> <span class=\"greek\">ἔγνως</span> … · <span class=\"greek\">νῦν</span> <span class=\"greek\">δέ</span>, se tivesses conhecido … ; mas, na realidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:42</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:40</a>; 9:41; 15:22, 24; 18:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:18</a> v.l., 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:16</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:11</a>; 7:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:16</a>.</p><p class=\"entry-text\">ⓑ Com artigo: neutro plural <span class=\"greek\">τὰ</span> <span class=\"greek\">ν</span>. (também escrito <span class=\"greek\">τανῦν</span>; cf. Tdf., Prol. p. 111), no que diz respeito à situação atual = agora (autores trágicos, Pla. e outros; POxy 743, 30 [2 b.c.]; 811; PTebt 315, 25; Jdth 9:5; 1 Esdr 1:31; Jos., C. Ap. 1, 217) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:29</a>; 17:30; 20:32; 27:22. <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">ὑμῖν</span>, pois agora vos digo isto 5:38. <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ν</span>. Hs 5, 7, 4 (TestLevi 10:1 v.l.).—<span class=\"greek\">τὸ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἔχον</span>, por ora (Dio Chrys. 21 [38], 42; Tob 7:11 BA v.l.; cf. Tat. 15, 2; 41, 1 <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">συνέχον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:25</a> (B-D-F §160).—A tradição manuscrita frequentemente apresenta alternância entre <span class=\"greek\">ν</span>. e <span class=\"greek\">νυνί</span>.—PTachau, ‘Einst’ u. ‘Jetzt’ im NT, ’72; FDanker, Proclamation Commentaries: Luke2, ’87, 47–57. B. 962f. DELG s.v. <span class=\"greek\">νυ</span>. M-M. TW.</p></section></article>\n"};
